      pt: ["Uma cordilheira que limita a parte sudoeste do planalto de Khorat e abrange o Parque Nacional Khao Yai.", "Localizado no território do Reino da Tailândia.", "Influenciado pelo clima de monções do Sudeste Asiático."],
