      hu: "A Tenasserim-hegység része, amely a határt képezi Thaiföld és a mianmari Kayin állam között.",
      ro: "O parte a lanțului Tenasserim, care formează granița dintre Thailanda și statul Kayin din Myanmar.",
      en: "A subrange of the Tenasserim Hills, forming the border between Thailand and Kayin State in Myanmar.",
      es: "Una parte de la cordillera de Tenasserim que forma la frontera entre Tailandia y el estado Kayin en Myanmar.",
      pt: "Uma parte da cordilheira de Tenasserim que forma a fronteira entre a Tailândia e o estado Kayin em Myanmar.",
      fr: "Une partie de la chaîne de montagnes Tenasserim qui forme la frontière entre la Thaïlande et l'État Karen au Myanmar.",
